    amenities: [
      { name: 'Fairmont Spa & Wellness', desc: 'An award-winning 2,500m² spa and wellness center. Facilities include 18 treatment rooms, a traditional Hammam for up to six guests, a 20-metre indoor pool, cryotherapy chamber, thermal suite (sauna, steam room, experience showers), salt room, and Japanese foot bath. Products from Natura Bissé and La Sultane de Saba.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682219/DSC_2622_sqykqb.jpg' },
      { name: 'Padel & Tennis Courts', desc: 'Two padel courts and two tennis courts set within the hotel\'s grounds — available to guests with a simple court reservation. Privé Passport members benefit from priority access and preferred court rates.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682356/FWP_Padel_4_copy_krpxu8.jpg' },
      { name: 'Orchid Tea Room', desc: 'The hotel\'s celebrated afternoon tea destination, set in a vibrant and serene space inspired by the orchid gardens. Each bite captures the essence of the season, with a menu inspired by the rustic charm and natural beauty of the 40-acre estate.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682402/Fairmont-Windsor-Park_Valentines-Day-2024_AFternoon-Tea_250124_0009_Edit_Web-Banner_bmuicj.jpg' },
    ],
    accommodations: [
      { num: '01', title: 'Rooms', body: 'Natural stone and soft textures create an elegant, sumptuous environment. Classic rooms feature circular windows, queen beds, and powerful walk-in showers from 25m². Superior rooms add a king bed, seating area, and more generous proportions from 36m².', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682488/FWP-Eaves-Quees-Room-1-1804x1200_szsnv7.jpg' },
      { num: '02', title: 'Fairmont Rooms', body: 'The hotel\'s mid-tier rooms offer a modern bathroom with both bathtub and separate walk-in shower, alongside state-of-the-art in-room amenities. These rooms combine authentic Fairmont design with commanding views of the landscaped grounds.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682570/FWP-Accessible-1_sglg4p.jpg' },
      { num: '03', title: 'Suites', body: 'From the Fairmont One-Bedroom Suite to the grandeur of the Luxury Two-Bedroom Suite — each with private balconies or terraces, separate living areas, and views across the grounds toward Windsor Great Park.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682569/DSC_3465-1802x1200_p9nqnz.jpg' },
    ],
    restaurants: [
      { name: '1215 Bar and Terrace', desc: 'An intimate and relaxed bar overlooking the south lawn, offering exclusive cocktails, premium spirits, and exquisite wines from behind a striking bar. Open daily for drinks, casual dining, and pre-dinner aperitifs — the ideal place to unwind in comfort and style at Fairmont Windsor Park.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682947/1215-Res-1800x1200_ecjfje.jpg' },
      { name: 'Il Giardino at 1215', desc: 'A modern Italian dining experience inspired by the vitality of Italy and the freshness of the hotel\'s walled garden. Elegant simplicity meets bold flavour, celebrating regional Italian cooking through a contemporary lens — from house-made pastas and vibrant crudi to dishes that honour the whole ingredient, from root to flower.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682949/1215-at-Fairmont-Windsor-Park-2-1804x1200_vjphlx.jpg' },
      { name: 'Greens Café', desc: 'A relaxed, private café nestled within the hotel\'s spa and wellness facility, designed exclusively for spa guests. Choose from freshly made produce and pressed juices, with menu guidance available from the wellness chef — thoughtfully curated with your health in mind.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775683008/Untitled-1_0002_Fairmont-January_food-2_pa4xfc.jpg' },
      { name: 'The Library Club', desc: 'Rich woods, plush leather, and the amber glow of an antique stone fireplace set the scene at The Library Club. An intimate and quietly grand space for cocktails, conversation, and evenings that move at your pace — with a menu to match, served Friday through Sunday from the afternoon onwards.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775682944/The-Library-Club-Web-6-600x400_j2ogbb.jpg' },
    ],
