    memberBenefits: ['Best Available rate', 'Room upgrade (subject to availability)', 'Early check-in / late check-out', 'Special room amenity — Upon arrival'],
    amenities: [
      { name: 'Mytha Spa', desc: 'Widely considered the finest spa in Türkiye, the Mytha Spa overlooks the Mediterranean in a peaceful hilltop setting. It offers a comprehensive range of treatments and therapies, with a steam room, sauna, and indoor pool.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775996403/000000909_d-maris-bay_indoor-spa-pool_k3lcwy.png' },
      { name: 'Six Private Beaches', desc: 'Six natural sandy beaches of extraordinary quality, each with a distinct character — from glamorous French Riviera-style beach clubs to quiet snorkelling coves.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775996587/D_Maris_Bay_La_Guérite_2_copy_itz5yj.jpg' },
      { name: 'Padel & Sports', desc: 'D-Gym features state-of-the-art Technogym equipment, padel, and tennis courts set within the resort\'s grounds.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775996926/D_Maris_Bay_Padel_Courts_copy_mbv38o.jpg' },
    ],
    accommodations: [
      { num: '01', title: 'Rooms', body: 'Spacious, airy rooms, flooded with light, boast Italian marble and polished teak tree wood. Choose a sea view for spellbinding vistas of the bay, or opt for the dramatic scenery of the mountains.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1777263553/D_Maris_Bay__Rooms_zq0cjs.jpg' },
      { num: '02', title: 'Suites', body: 'Choose a suite for exclusive privileges, an abundance of space and sumptuous details, with sweeping views over the bay or volcanic mountains. Elegant details, such as sleek travertine stone, set suites apart in next-level luxury.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776614826/D_Maris_Bay_Room_Balcony_copy_blt4gd.jpg' },
      { num: '03', title: 'The Villa', body: 'The sprawling 310-sqm D Maris Bay Villa is an indulgent hideaway complete with its own private pool in vivid, lush gardens. Bathrooms are adorned in Calacatta marble, and each of the two guest rooms boasts its own walk-in wardrobe. Your fully-equipped Gaggenau kitchen has a wine cooler and a dining room that hosts up to 8 people.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1777263547/DMB_14_9961_copy_hjycmc.jpg' },
    ],
    restaurants: [
      { name: 'La Guérite', desc: 'The sophisticated essence of Cannes and St. Barths, brought to the shores of the Datça Peninsula. Fresh seafood and attentive service in a stylish Mediterranean setting, complemented by a sea breeze and a happy-hour rhythm that carries into sunset.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775995915/000003218_d-maris-bay_la-guerite-558x315px_edrkug.jpg' },
      { name: 'Manos', desc: 'Rustic decor and mosaic flooring set the stage for a warm tavern atmosphere, with the freshest seafood and an assortment of Greek mezes. Manos enriches the experience with Greek cultural traditions and festive activities, leading guests on a delectable Mediterranean journey to the rhythm of the music.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1775995909/000003217_d-maris-bay_manos-menu-558x315px_dtd7jo.jpg' },
      { name: 'D Maris Kitchen', desc: 'Nestled at The Bay Beach, D Maris Kitchen blends the essence of Aegean and Anatolian cuisines with a modern, refined touch. From local olive oil dishes to mezzes, from hearty stews to refined presentations, every plate reflects the traces of the past and a contemporary aesthetic.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776634611/D_Maris_Bay__D_Maris_Kitchen_copy_vbdwqa.jpg' },
      { name: 'Nusr-Et', desc: 'Located at The Bay Beach, Nusr-Et creates a memorable culinary experience by serving tender steaks with magnificent theatrical touches in an engaging presentation.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776634849/D_Maris_Bay__Nusr-Et_copy_thvtj1.jpg' },
      { name: 'Zuma', desc: 'Authentic Japanese flavors in a modern twist, served Izakaya-style. With its unique ambiance, Zuma offers a visual spectacle set against a breathtaking panoramic sea view.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776634717/D_Maris_Bay_Zuma_Outdoor_copy_omyxzc.jpg' },
      { name: 'Aurora Capri', desc: 'A legendary name from the heart of Capri, Aurora Capri brings over 130 years of Italian culinary heritage to the shores of D Maris Bay. Known for its iconic "Pizzallacqua®" and timeless flavors, this celebrated restaurant blends Campanian traditions with contemporary finesse. Curated by Mia D\'Alessio and Chef Franco Aversa, Aurora Capri offers an elegant dining experience shaped by generations of passion, creativity, and Mediterranean charm.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776635042/D_Maris_Bay__Aurora_Capri_copy_dvdzml.jpg' },
    ],
