    accommodations: [
      { num: '01', title: 'Rooms & Suites', body: 'Discover comfort with a traditional twist in the Main Hotel Seaview Rooms and Suites. Revel in spacious elegance and mesmerizing sea views, creating a serene ambiance for an unforgettable stay.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776016999/Superior_Room_Large_uve4o8.jpg' },
      { num: '02', title: 'Bungalows with Private Pools', body: 'Experience pure luxury at the Bungalows with Private Pools, where timeless design seamlessly merges with the irresistible allure of Cretan hospitality. Each bungalow is a testament to sophistication, offering a harmonious retreat that ensures an indulgent escape from the ordinary.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776017420/Superior_Bungalow_bedroom-scaled-rjqmsxjrtdhuxulnr6lp9xakxu2c9vfgzqsxnxbx9s_jka9b6.jpg' },
      { num: '03', title: 'Minoan Royalty Villas', body: 'Immerse yourself in seaside bliss at the Minoan Royalty Villas with Private Pool. Revel in the luxury of close access to the sandy shores and wake up to the gentle sounds of the sea. An idyllic retreat where you can enjoy classic elegance amidst the beauty of Elounda\'s beach.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776017417/KokotosElounda2442-scaled-rjqnhrgacthjn0j7rezwn5pxv9oem107en7p22iiwg_xjv0zy.jpg' },
      { num: '04', title: 'Minoan Palace', body: 'Introducing "Minoan Palace," Elounda Mare Hotel\'s new 4-bedroom beachfront villa. Luxuriate in a 76sqm master bedroom, three spacious bedrooms with en-suite bathrooms, and al-fresco dining on the veranda. Elevator access, private chef\'s pantry, large seawater pool, and direct beach access ensure an unforgettable family retreat.', img: 'https://res.cloudinary.com/dfjqa5f05/image/upload/q_auto/f_auto/v1776016994/Minoan_Palace_outdoor_1_Large_pn4tvy.jpg' },
    ],
